how_to_obtain.command:
Connect-MgGraph -Scopes "UserAuthenticationMethod.Read.All","Directory.Read.All"
$breakGlassAccounts = Get-MgUser -Filter "displayName eq 'BreakGlass'" -All
foreach ($account in $breakGlassAccounts) {
  $methods = Get-MgUserAuthenticationMethod -UserId $account.Id
  Write-Output "Account: $($account.UserPrincipalName) | MFA Methods: $($methods.Count)"
}

Connect-MgGraph -Scopes "Policy.Read.All"
$policies = Get-MgIdentityConditionalAccessPolicy
$legacyBlock = $policies | Where-Object {
  $_.Conditions.ClientAppTypes -contains "exchangeActiveSync" -or
  $_.Conditions.ClientAppTypes -contains "other"
}
$legacyBlock | Select-Object DisplayName, State, @{N="GrantControls";E={$_.GrantControls.BuiltInControls}}

Connect-MgGraph -Scopes "Policy.Read.All"
$policies = Get-MgIdentityConditionalAccessPolicy
foreach ($p in $policies) {
  $session = $p.SessionControls
  Write-Output "Policy: $($p.DisplayName) | SignInFrequency: $($session.SignInFrequency?.Value) $($session.SignInFrequency?.Type) | PersistentSession: $($session.PersistentBrowser?.IsEnabled)"
}

Connect-MgGraph -Scopes "Policy.Read.All","Application.Read.All"
$policies = Get-MgIdentityConditionalAccessPolicy | Where-Object {
  $_.GrantControls.BuiltInControls -contains "mfa"
}
foreach ($p in $policies) {
  $apps = $p.Conditions.Applications.IncludeApplications
  Write-Output "Policy: $($p.DisplayName) | Apps: $($apps -join ', ')"
}

Connect-MgGraph -Scopes "Policy.Read.All","Application.Read.All"
$allApps = Get-MgApplication -All | Select-Object -ExpandProperty AppId
$mfaPolicies = Get-MgIdentityConditionalAccessPolicy | Where-Object {
  $_.GrantControls.BuiltInControls -contains "mfa" -and $_.State -eq "enabled"
}
$coveredApps = $mfaPolicies.Conditions.Applications.IncludeApplications | Sort-Object -Unique
$unprotected = $allApps | Where-Object { $_ -notin $coveredApps -and $_ -ne "All" }
Write-Output "Unprotected app count: $($unprotected.Count)"

Connect-MgGraph -Scopes "Policy.Read.All"
$namedLocations = Get-MgIdentityConditionalAccessNamedLocation
$policies = Get-MgIdentityConditionalAccessPolicy | Where-Object { $_.State -eq "enabled" }
foreach ($p in $policies) {
  $excludedLocations = $p.Conditions.Locations.ExcludeLocations
  if ($excludedLocations) {
    $locNames = $namedLocations | Where-Object { $_.Id -in $excludedLocations } | Select-Object -ExpandProperty DisplayName
    Write-Output "Policy: $($p.DisplayName) | ExcludedLocations: $($locNames -join ', ')"
  }
}

Connect-ExchangeOnline
Get-CASMailbox -ResultSize Unlimited | Where-Object {
  $_.SmtpClientAuthenticationDisabled -eq $false -or
  $_.ImapEnabled -eq $true -or
  $_.PopEnabled -eq $true
} | Select-Object DisplayName, SmtpClientAuthenticationDisabled, ImapEnabled, PopEnabled
